67	 */
68	
69	@RestController
70	@CrossOrigin(exposedHeaders = "errors, content-type")
71	@RequestMapping("/api")
72	public class OwnerRestControllerV1 implements OwnersApi {
73	
74	    /**
75	     * Basic syntactic check for an email address: a non-empty local part, an '@', and a domain with
76	     * at least one dot and a two-or-more letter top-level label. Case is ignored here; accepted
77	     * addresses are lower-cased before being stored.
78	     */
79	    private static final Pattern EMAIL_PATTERN =
80	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
81	
82	    /** An owner's postcode, when supplied, must be exactly four digits. */
83	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
84	
85	    /**
86	     * Disposable e-mail domains an owner may not sign up with. An email whose domain (the part after
87	     * the '@', compared case-insensitively) is on this blocklist is rejected with a 400.
88	     */
89	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
90	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
91	
92	    /**
93	     * Dedicated logger for audit side-effects. Emitting audit records on a well-known, separately
94	     * named logger keeps them addressable independently of the class's diagnostic logging.
95	     */
96	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
97	
98	    /**
99	     * Maximum number of owners a single city may contain. A create that would take the owner's city
100	     * to more than this many owners - i.e. the city already holds this many - is rejected with a 409.
101	     */
102	    private static final int CITY_OWNER_LIMIT = 50;
103	
104	    /**
105	     * Maximum number of owners that may be registered on a single day. A create that would take the
106	     * number of owners sharing a {@code registrationDate} beyond this many - i.e. that many owners
107	     * have already been created that day - is rejected with a 429.
108	     */
109	    private static final int DAILY_OWNER_LIMIT = 100;
110	
111	    /**
112	     * Number of owners that must already have been created for a given day before the create
113	     * response flags a bulk sign-up. When more than this many owners already share a
114	     * {@code registrationDate}, the response's {@code bulkSignupWarning} is {@code true}.
115	     */
116	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
117	
118	    /**
119	     * Fixed list of public holidays. A registration date that lands on one of these dates is treated
120	     * like a weekend and rolled forward to the next non-holiday business day.
121	     */
122	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
123	        LocalDate.of(2026, 1, 1),
124	        LocalDate.of(2026, 1, 26),
125	        LocalDate.of(2026, 4, 25),
126	        LocalDate.of(2026, 12, 25),
127	        LocalDate.of(2026, 12, 28));
128	
129	    /**
130	     * Request header carrying the client-supplied idempotency key. When a create repeats with a key
131	     * already seen, the originally created owner is returned instead of creating a duplicate.
132	     */
133	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
134	
135	    private final ClinicService clinicService;
136	
137	    private final OwnerMapper ownerMapper;
138	
139	    private final PetMapper petMapper;
140	
141	    private final VisitMapper visitMapper;
142	
143	    private final HttpServletRequest request;
144	
145	    /**
146	     * Remembers the owner produced by each previously seen {@code Idempotency-Key}, so a repeated
147	     * create with an already-seen key returns the originally created owner rather than a duplicate.
148	     */
149	    private final Map<String, OwnerDto> idempotencyStore = new ConcurrentHashMap<>();
150	
151	    public OwnerRestControllerV1(ClinicService clinicService,
152	                                 OwnerMapper ownerMapper,
153	                                 PetMapper petMapper,
154	                                 VisitMapper visitMapper,
155	                                 HttpServletRequest request) {
156	        this.clinicService = clinicService;
157	        this.ownerMapper = ownerMapper;
158	        this.petMapper = petMapper;
159	        this.visitMapper = visitMapper;
160	        this.request = request;
161	    }
162	
163	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
164	    @Override
165	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
166	        Collection<Owner> owners;
167	        if (lastName != null) {
168	            owners = this.clinicService.findOwnerByLastName(lastName);
169	        } else {
170	            owners = this.clinicService.findAllOwners();
171	        }
172	        if (owners.isEmpty()) {
173	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
174	        }
175	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Override
180	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
181	        Owner owner = this.clinicService.findOwnerById(ownerId);
182	        if (owner == null) {
183	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
184	        }
185	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
186	        ownerDto.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
187	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
188	    }
189	
190	    /**
191	     * Determines whether the supplied day currently holds more than {@link #BULK_SIGNUP_WARNING_THRESHOLD}
192	     * owners sharing that {@code registrationDate}, which flags an unusually high volume of same-day
193	     * owner sign-ups.
194	     *
195	     * @param registrationDate the day to inspect, or {@code null}
196	     * @return {@code true} when more than the threshold of owners are registered on that day
197	     */
198	    private boolean isBulkSignupDay(LocalDate registrationDate) {
199	        return registrationDate != null
200	            && countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
201	    }
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Override
205	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
206	        String idempotencyKey = idempotencyKey();
207	        if (idempotencyKey != null) {
208	            OwnerDto existing = this.idempotencyStore.get(idempotencyKey);
209	            if (existing != null) {
210	                return new ResponseEntity<>(existing, HttpStatus.OK);
211	            }
212	        }
213	        Owner owner = buildOwnerToCreate(ownerFieldsDto);
214	        boolean bulkSignupWarning = enforceCreateLimits(owner) > BULK_SIGNUP_WARNING_THRESHOLD;
215	        finalizeOwnerForCreate(owner);
216	        this.clinicService.saveOwner(owner);
217	        ResponseEntity<OwnerDto> response = createdOwnerResponse(owner, bulkSignupWarning);
218	        if (idempotencyKey != null) {
219	            this.idempotencyStore.put(idempotencyKey, response.getBody());
220	        }
221	        return response;
222	    }
223	
224	    /**
225	     * Returns the client-supplied {@code Idempotency-Key} for the current request, or {@code null}
226	     * when the header is absent or blank.
227	     */
228	    private String idempotencyKey() {
229	        String key = this.request.getHeader(IDEMPOTENCY_KEY_HEADER);
230	        return StringUtils.hasText(key) ? key : null;
231	    }
232	
233	    /**
234	     * Resolves, validates and maps a create request into a fully-normalized {@link Owner} that is
235	     * ready to persist except for the derived fields assigned by {@link #finalizeOwnerForCreate}. The
236	     * submitted address is canonicalized, the required fields and the optional postcode and
237	     * registration date are validated, and the mapped owner's telephone and email are normalized. The
238	     * registration date is defaulted to the server date when absent and rolled forward to a business
239	     * day. The household id and identity key are derived; a create that would join an already-populated
240	     * household is rejected unless it opts in with {@code sharesHousehold}, and otherwise a soft-match
241	     * duplicate is flagged.
242	     *
243	     * @param ownerFieldsDto the submitted owner fields
244	     * @return the normalized owner, not yet persisted
245	     */
246	    private Owner buildOwnerToCreate(OwnerFieldsDto ownerFieldsDto) {
247	        resolveAddressFields(ownerFieldsDto);
248	        validateRequiredFields(ownerFieldsDto);
249	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
250	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
251	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
252	        owner.setEmail(normalizeEmail(owner.getEmail()));
253	        validateRegistrationDate(owner.getRegistrationDate());
254	        if (owner.getRegistrationDate() == null) {
255	            owner.setRegistrationDate(LocalDate.now());
256	        }
257	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
258	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
259	        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
260	        owner.setIdentityKey(buildIdentityKey(owner));
261	        if (!sharesHousehold) {
262	            rejectHouseholdDuplicate(owner.getHouseholdId());
263	        }
264	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
265	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
266	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
267	        return owner;
268	    }
269	
270	    /**
271	     * Enforces the per-city and per-day capacity limits for a new owner, in that order. A create that
272	     * would take the owner's city beyond {@link #CITY_OWNER_LIMIT} owners is rejected with a 409, and
273	     * one that would take the owner's registration date beyond {@link #DAILY_OWNER_LIMIT} owners is
274	     * rejected with a 429. The returned count is the number of owners already sharing the owner's
275	     * registration date, measured before it is saved, which the caller uses to decide the response's
276	     * {@code bulkSignupWarning}.
277	     *
278	     * @param owner the normalized owner about to be created
279	     * @return the number of owners already registered on the owner's registration date
280	     */
281	    private long enforceCreateLimits(Owner owner) {
282	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
283	            throw new OwnerCityFullException(owner.getCity());
284	        }
285	        long ownersRegisteredOnDay = countOwnersRegisteredOn(owner.getRegistrationDate());
286	        if (ownersRegisteredOnDay >= DAILY_OWNER_LIMIT) {
287	            throw new OwnerDailyLimitException(owner.getRegistrationDate());
288	        }
289	        return ownersRegisteredOnDay;
290	    }
291	
292	    /**
293	     * Assigns the derived fields that only apply once the owner has cleared the create checks: its
294	     * de-duplicated customer code, the number of existing namesakes, and the household size once the
295	     * new owner is added.
296	     *
297	     * @param owner the normalized owner about to be created
298	     */
299	    private void finalizeOwnerForCreate(Owner owner) {
300	        owner.setCustomerCode(buildCustomerCode(owner));
301	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
302	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
303	    }
304	
305	    /**
306	     * Builds the {@code 201 Created} response for a freshly persisted owner: maps it to a DTO, emits
307	     * the audit record, sets the {@code bulkSignupWarning} the caller computed from the pre-save daily
308	     * count, and adds the {@code Location} header pointing at the new owner.
309	     *
310	     * @param owner the owner that has just been saved, with its generated id populated
311	     * @param bulkSignupWarning whether the response should flag an unusually high same-day sign-up volume
312	     * @return the created-owner response
313	     */
314	    private ResponseEntity<OwnerDto> createdOwnerResponse(Owner owner, boolean bulkSignupWarning) {
315	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
316	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
317	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
318	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
319	        ownerDto.setBulkSignupWarning(bulkSignupWarning);
320	        HttpHeaders headers = new HttpHeaders();
321	        headers.setLocation(UriComponentsBuilder.newInstance()
322	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
323	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
324	    }
325	
326	    /**
327	     * Canonicalizes the submitted address fields into the form that is validated, stored and
328	     * returned, before any required-field check or mapping runs. This is the single place a create
329	     * request's address input is resolved.
330	     *
331	     * <p>The structured fields are preferred over the flat input for backward compatibility: when a
332	     * non-blank {@code addressLine1} is supplied, {@code addressLine1} and the optional
333	     * {@code addressLine2} are {@link AddressNormalizer#normalize normalized} in place and the flat
334	     * {@code address} is set to the composed value - the normalized {@code addressLine1}, with a
335	     * single space and the normalized {@code addressLine2} appended when {@code addressLine2} is
336	     * present. When no structured line is supplied the flat {@code address} is normalized in place,
337	     * exactly as before. Either way everything downstream - the required-field check, the mapping onto
338	     * {@link Owner} and the response - sees the canonical address rather than the raw input. A value
339	     * that is blank only after normalization is left blank here and rejected later by
340	     * {@link #validateRequiredFields}.
341	     *
342	     * @param ownerFieldsDto the submitted owner fields, mutated in place with the resolved address
343	     */
344	    private void resolveAddressFields(OwnerFieldsDto ownerFieldsDto) {
345	        String line1 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
346	        String line2 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
347	        if (!line1.isEmpty()) {
348	            ownerFieldsDto.setAddressLine1(line1);
349	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
350	            ownerFieldsDto.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
351	        }
352	        else {
353	            ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
354	        }
355	    }
356	
357	    /**
358	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
359	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
360	     * so the client receives a 400 whose {@code errors} array lists each missing field. The address is
361	     * checked in its resolved form (see {@link #resolveAddressFields}), which is satisfied by either a
362	     * non-blank {@code addressLine1} or the flat {@code address}, so a value that is blank only after
363	     * normalization is still rejected.
364	     *
365	     * @param ownerFieldsDto the submitted owner fields
366	     */
367	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
368	        List<String> missingFields = new ArrayList<>();
369	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
370	            missingFields.add("firstName");
371	        }
372	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
373	            missingFields.add("lastName");
374	        }
375	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
376	            missingFields.add("address");
377	        }
378	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
379	            missingFields.add("city");
380	        }
381	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
382	            missingFields.add("telephone");
383	        }
384	        if (!missingFields.isEmpty()) {
385	            throw new MissingOwnerFieldsException(missingFields);
386	        }
387	    }
388	
389	    /**
390	     * Validates an owner's optional postcode. Postcode is optional, so a missing or blank value is
391	     * accepted unchanged. When a value is supplied it must be exactly four digits; and when the owner's
392	     * city maps to a known region the postcode must fall within that region's inclusive range (checked
393	     * via {@link OwnerLocality#postcodeMatchesCity}, which owns the region table). A city with no known
394	     * region accepts any 4-digit postcode. A malformed or out-of-range postcode is rejected with a 400
395	     * whose {@code errors} array lists {@code postcode}.
396	     *
397	     * @param postcode the submitted postcode, or {@code null} when none was supplied
398	     * @param city the owner's city, whose region determines the acceptable postcode range
399	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
400	     */
401	    private void validatePostcode(String postcode, String city) {
402	        if (!StringUtils.hasText(postcode)) {
403	            return;
404	        }
405	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
406	            throw new InvalidOwnerFieldsException(List.of("postcode"));
407	        }
408	        if (!OwnerLocality.postcodeMatchesCity(postcode, city)) {
409	            throw new InvalidOwnerFieldsException(List.of("postcode"));
410	        }
411	    }
412	
413	    /**
414	     * Validates an owner's optional registration date. Registration date is optional, so a missing
415	     * value is accepted (the create later defaults it to the server date). When a value is supplied
416	     * it may not lie in the future: a date later than the server's current date is rejected with a
417	     * 400 whose {@code errors} array lists {@code registrationDate}.
418	     *
419	     * @param registrationDate the submitted registration date, or {@code null} when none was supplied
420	     * @throws InvalidOwnerFieldsException if a supplied date is later than the server date
421	     */
422	    private void validateRegistrationDate(LocalDate registrationDate) {
423	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
424	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
425	        }
426	    }
427	
428	    /**
429	     * Rejects a submitted owner that would join a household which already has a member. Because the
430	     * {@code householdId} is derived deterministically from the owner's last name and postcode, any
431	     * existing owner sharing that id is the same household, so a second such owner is reported to the
432	     * client as a 409 Conflict. A request may knowingly bypass this block by opting in with
433	     * {@code sharesHousehold}, in which case this check is not performed.
434	     *
435	     * @param householdId the derived household identifier of the owner about to be created
436	     */
437	    private void rejectHouseholdDuplicate(String householdId) {
438	        boolean duplicate = this.clinicService.findAllOwners().stream()
439	            .filter(existing -> !existing.isDeleted())
440	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
441	        if (duplicate) {
442	            throw new DuplicateOwnerIdentityException(householdId);
443	        }
444	    }
445	
446	    /**
447	     * Derives the owner's {@code identityKey}, formatted
448	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the telephone
449	     * and email have already been normalized. The household segment always carries the owner's
450	     * deterministic {@code householdId}, since owners with the same last name and postcode belong to
451	     * the same household automatically.
452	     *
453	     * @param owner the normalized owner about to be created, with its {@code householdId} already set
454	     * @return the derived identity key
455	     */
456	    private String buildIdentityKey(Owner owner) {
457	        String email = StringUtils.hasText(owner.getEmail()) ? owner.getEmail() : "";
458	        return owner.getTelephone() + "|" + email + "|" + owner.getHouseholdId();
459	    }
460	
461	    /**
462	     * Detects a soft-match duplicate for the owner about to be created. A soft match is an owner that
463	     * shares an existing owner's {@code lastName} (case-insensitively) and {@code postcode} while
464	     * having a different normalized {@code telephone}. Such an owner is still created, but is flagged
465	     * as a possible duplicate of the matching owner. This is only consulted for owners that did not
466	     * opt into a shared household: an owner that declares {@code sharesHousehold} is a known household
467	     * member, not a suspected duplicate, so it is never flagged. The comparison only applies when a
468	     * postcode was supplied, since both owners must share one; when several existing owners match, the
469	     * earliest (lowest id) is used.
470	     *
471	     * @param owner the normalized owner about to be created, with its telephone already normalized
472	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
473	     */
474	    private Integer findPossibleDuplicate(Owner owner) {
475	        if (!StringUtils.hasText(owner.getPostcode())) {
476	            return null;
477	        }
478	        return this.clinicService.findAllOwners().stream()
479	            .filter(existing -> !existing.isDeleted())
480	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName()))
481	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
482	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
483	            .map(Owner::getId)
484	            .filter(id -> id != null)
485	            .min(Integer::compareTo)
