489	    /**
490	     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
491	     * blank value is left untouched. When a value is supplied it must be a syntactically valid
492	     * address; the accepted value is lower-cased before it is stored and returned.
493	     *
494	     * @param email the raw email value submitted by the client, or {@code null}
495	     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
496	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
497	     */
498	    private String normalizeEmail(String email) {
499	        if (!StringUtils.hasText(email)) {
500	            return email;
501	        }
502	        if (!EMAIL_PATTERN.matcher(email).matches()) {
503	            throw new InvalidOwnerFieldsException(List.of("email"));
504	        }
505	        String normalized = email.toLowerCase();
506	        String domain = normalized.substring(normalized.indexOf('@') + 1);
507	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
508	            throw new InvalidOwnerFieldsException(List.of("email"));
509	        }
510	        return normalized;
511	    }
