273	     * @return the {@link ValidationMessageDto} describing the rejected field
274	     */
275	    private ValidationMessageDto toValidationMessage(FieldError fieldError) {
276	        String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
277	        String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
278	        String message = "Field '%s' %s (rejected value: %s)".formatted(
279	            fieldError.getField(),
280	            defaultMessage,
281	            rejectedValue);
282	        return new ValidationMessageDto(message)
283	            .putAdditionalProperty("field", fieldError.getField())
284	            .putAdditionalProperty("rejectedValue", rejectedValue)
